final class LocalTaskConfigurationRepository implements TaskConfigurationRepository { const LocalTaskConfigurationRepository(this.dao); final TaskConfigurationDao dao; @override Future<List<TaskPriority>> getPriorities() async=>(await dao.getPriorities()).map((e)=>e.toTaskPriorityDomain()).toList(); @override Future<TaskPriority?> getPriorityById(String id) async=>(await dao.getPriorityById(id))?.toTaskPriorityDomain(); @override Future<List<TaskCategory>> getCategories() async=>(await dao.getCategories()).map((e)=>e.toTaskCategoryDomain()).toList(); @override Future<TaskCategory?> getCategoryById(String id) async=>(await dao.getCategoryById(id))?.toTaskCategoryDomain(); @override Future<List<ConfidentialityLevel>> getConfidentialityLevels() async=>(await dao.getConfidentialityLevels()).map((e)=>e.toConfidentialityLevelDomain()).toList(); @override Future<List<ApprovalRule>> getApprovalRules() async=>(await dao.getApprovalRules()).map((e)=>e.toApprovalRuleDomain()).toList(); @override Future<List<EscalationRule>> getEscalationRules() async=>(await dao.getEscalationRules()).map((e)=>e.toEscalationRuleDomain()).toList(); @override Future<List<NotificationTemplate>> getNotificationTemplates() async=>(await dao.getNotificationTemplates()).map((e)=>e.toNotificationTemplateDomain()).toList(); @override Future<List<TaskTemplate>> getTaskTemplates() async=>(await dao.getTaskTemplates()).map((e)=>e.toTaskTemplateDomain()).toList(); }
